from PySpice.Spice.Netlist import Circuit
from PySpice.Unit import *
import numpy as np
from typing import List, Dict, Optional
import matplotlib.pyplot as plt
from scipy.interpolate import interp1d

class CircuitParams():
    vin: float = 12
    c_value: float = 44e-6
    duty_cycle: float = 0.5
    current_out: float = 2.9
    esr: float = 0.1
    l_value: float = 10e-6
    l_resistance: float = 19.5e-3
    transistor_on_resistance: float = 1e-9
    frequency: float = 312500

class BuckConverter:
    def __init__(self, params: CircuitParams):
        self.vin = params.vin
        self.freq = params.frequency
        self.l_value = params.l_value
        self.c_value = params.c_value
        self.duty_cycle = params.duty_cycle
        self.l_resistance = params.l_resistance
        self.current_out = params.current_out
        self.transistor_on_resistance = params.transistor_on_resistance
        self.vout = self.vin * self.duty_cycle
        self.r_load = self.vout / self.current_out
        self.period = 1 / self.freq
        self.circuit = None
        self.esr = params.esr
        self.circuit_params = params  # Store original parameters

    def build_circuit(self):
        circuit = Circuit('Buck Converter')
        circuit.V('in', 'vin', 'gnd', self.vin)
        
        ton = self.duty_cycle * self.period * 1e6
        period_us = self.period * 1e6
        circuit.V('gate', 'g', 'gnd', f'PULSE(0 10 0 1n 1n {ton}us {period_us}us)')
        
        circuit.S('1', 'vin', 'sw', 'g', 'gnd', model='SWITCH')
        circuit.model('SWITCH', 'SW', ron=self.transistor_on_resistance, vt=1, vh=0)
        
        circuit.D('1', 'gnd', 'sw', model='MYDIODE')
        circuit.model('MYDIODE', 'D', is_=1e6)
            
        circuit.L('1', 'sw', 'out', self.l_value)
        circuit.R('L1', 'out', 'out_c', self.l_resistance)

        circuit.C('1', 'out_c', 'c_res', self.c_value)
        circuit.R('C1', 'c_res', 'gnd', self.esr)
        
        circuit.R('load', 'out_c', 'gnd', self.r_load)
        
        self.circuit = circuit
        return circuit

    def run_simulation(self):
        if self.circuit is None:
            self.build_circuit()
                
        simulator = self.circuit.simulator(temperature=25, nominal_temperature=25)
        
        delta = self.period * 600
        end_time = delta + self.period
        step_time = self.period / 1000
        print(f"Step time: {step_time}")
        
        analysis = simulator.transient(
            step_time=step_time,
            start_time=delta,
            end_time=end_time,
            use_initial_condition=False
        )
            
        # Vectorize data extraction
        sim_data = np.array([
            [float(v) for v in analysis['g']],
            [float(v) for v in analysis['out_c']],
            [float(v) for v in analysis['out']]
        ])
        
        sim_time = (np.array([float(t) for t in analysis.time]) - delta) * 1e6
        
        print(sim_time)

        # Vectorized calculations
        v_l_sense = sim_data[2] - sim_data[1]
        sim_current = v_l_sense / self.l_resistance
        
        
        result = {
            'out_c': sim_data[1],
            'sim_current': sim_current,
            'time': sim_time,
            'pwm': sim_data[0]
        }
        
        return result
    
    def calculate_fitness(self, simulated, real_data):
        """Calculate how well the simulation matches real data using mean squared error."""
        # Extract data
        sim_voltage = simulated['out_c']
        sim_current = simulated['sim_current']
        sim_time = simulated['time']
        
        real_voltage = np.array(real_data['voltage'])
        real_current = np.array(real_data['current'])
        real_time = np.array(real_data['time'])
        
        # Ensure time ranges align
        min_time = max(min(sim_time), min(real_time))
        max_time = min(max(sim_time), max(real_time))
        
        # Filter data to common time range
        real_mask = (real_time >= min_time) & (real_time <= max_time)
        real_time_filtered = real_time[real_mask]
        real_voltage_filtered = real_voltage[real_mask]
        real_current_filtered = real_current[real_mask]
        
        # Interpolate simulation data to match real data time points
        voltage_interp = interp1d(sim_time, sim_voltage, bounds_error=False, fill_value="extrapolate")
        current_interp = interp1d(sim_time, sim_current, bounds_error=False, fill_value="extrapolate")
        
        sim_voltage_aligned = voltage_interp(real_time_filtered)
        sim_current_aligned = current_interp(real_time_filtered)
        
        # Calculate mean squared error
        voltage_mse = np.mean((sim_voltage_aligned - real_voltage_filtered) ** 2)
        current_mse = np.mean((sim_current_aligned - real_current_filtered) ** 2)
        
        # Combined fitness (lower is better)
        fitness = voltage_mse + current_mse
        
        return 1 / (1 + fitness)  # Convert to a value where higher is better
    
    def optimize_parameters(self, real_data, 
                           population_size=20, 
                           generations=10,
                           mutation_rate=0.2,
                           param_ranges=None):
        import random
        from copy import deepcopy
        
        # Define parameter ranges if not provided
        if param_ranges is None:
            param_ranges = {
                'vin': (8.0, 15.0),
                'duty_cycle': (0.2, 0.8),
                'l_value': (1e-6, 50e-6),
                'c_value': (10e-6, 150e-6)
            }
        
        # Create initial population
        population = []
        for _ in range(population_size):
            params = deepcopy(self.circuit_params)
            params.vin = random.uniform(*param_ranges['vin'])
            params.duty_cycle = random.uniform(*param_ranges['duty_cycle'])
            params.l_value = random.uniform(*param_ranges['l_value'])
            params.c_value = random.uniform(*param_ranges['c_value'])
            population.append(params)
        
        best_params = None
        best_fitness = -float('inf')
        
        # Evolution loop
        for gen in range(generations):
            print(f"Generation {gen+1}/{generations}")
            
            # Evaluate fitness
            fitness_scores = []
            for params in population:
                # Create a temporary converter with these parameters
                temp_converter = BuckConverter(params)
                try:
                    sim_data = temp_converter.run_simulation()
                    fitness = self.calculate_fitness(sim_data, real_data)
                except Exception as e:
                    print(f"Simulation failed: {e}")
                    fitness = 0  # Penalize failed simulations
                
                fitness_scores.append(fitness)
                
                # Track best solution
                if fitness > best_fitness:
                    best_fitness = fitness
                    best_params = deepcopy(params)
                    print(f"New best fitness: {best_fitness}")
                    print(f"Parameters: Vin={params.vin}V, Duty={params.duty_cycle}, L={params.l_value*1e6}µH, C={params.c_value*1e6}µF")
            
            # Select parents (tournament selection)
            def tournament_select(population, fitness_scores, tournament_size=3):
                tournament_indices = random.sample(range(len(population)), tournament_size)
                tournament_fitness = [fitness_scores[i] for i in tournament_indices]
                winner_idx = tournament_indices[tournament_fitness.index(max(tournament_fitness))]
                return population[winner_idx]
            
            # Create next generation
            new_population = []
            
            # Elitism: keep the best individual
            elite_idx = fitness_scores.index(max(fitness_scores))
            new_population.append(deepcopy(population[elite_idx]))
            
            # Fill rest of population
            while len(new_population) < population_size:
                # Select parents
                parent1 = tournament_select(population, fitness_scores)
                parent2 = tournament_select(population, fitness_scores)
                
                # Crossover
                child = deepcopy(parent1)
                if random.random() < 0.7:  # Crossover probability
                    # Randomly select parameters to inherit from parent2
                    for param in param_ranges.keys():
                        if random.random() < 0.5:
                            setattr(child, param, getattr(parent2, param))
                
                # Mutation
                for param, (min_val, max_val) in param_ranges.items():
                    if random.random() < mutation_rate:
                        current_val = getattr(child, param)
                        # Gaussian mutation with stddev of 10% of parameter range
                        stddev = 0.1 * (max_val - min_val)
                        new_val = current_val + random.gauss(0, stddev)
                        # Ensure value stays within bounds
                        new_val = max(min_val, min(max_val, new_val))
                        setattr(child, param, new_val)
                
                new_population.append(child)
            
            # Update population
            population = new_population
        
        print("\nOptimization completed")
        print(f"Best fitness: {best_fitness}")
        print(f"Optimized parameters: Vin={best_params.vin}V, Duty={best_params.duty_cycle}, " +
              f"L={best_params.l_value*1e6}µH, C={best_params.c_value*1e6}µF")
        
        return best_params
    
