processed_real_data = {"pwm": [], "voltage": [], "current": [], "time": []}

is_first_one = True
for x in range(len(real_data['pwm'])):
    if real_data['pwm'][x] == 0:
        is_first_one = False
    if real_data['pwm'][x] == 1 and is_first_one == False:
        break
    processed_real_data['pwm'].append(real_data['pwm'][x])
    processed_real_data['voltage'].append(real_data['voltage'][x])
    processed_real_data['current'].append(real_data['current'][x])
    processed_real_data['time'].append(real_data['time'][x])

# Run optimization
optimized_params = converter.optimize_parameters(processed_real_data, 
                                                population_size=30, 
                                                generations=3)

# Create converter with optimized parameters
optimized_converter = BuckConverter(optimized_params)
sim_data = optimized_converter.run_simulation()

# Plot comparison
plt.figure(figsize=(12, 8))
plt.subplot(2, 1, 1)
plt.plot(processed_real_data['time'], processed_real_data['voltage'], 'b-', label='Real Voltage')
plt.plot(sim_data['time'], sim_data['out_c'], 'r--', label='Simulated Voltage')
plt.legend()
plt.title('Voltage Comparison')

plt.subplot(2, 1, 2)
plt.plot(processed_real_data['time'], processed_real_data['current'], 'b-', label='Real Current')
plt.plot(sim_data['time'], sim_data['sim_current'], 'r--', label='Simulated Current')
plt.legend()
plt.title('Current Comparison')
plt.tight_layout()
plt.show()